items.referenceSolution:
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

public class Main {
    public static void main(String[] args) {
        LocalDate 发券 = LocalDate.of(2026, 9, 3);
        LocalDate 过期 = 发券.plusDays(5);

        System.out.println("过了几天：" + ChronoUnit.DAYS.between(发券, 过期));
        System.out.println("止比起晚：" + 过期.isAfter(发券));
        System.out.println("起是星期几：" + 发券.getDayOfWeek());
    }
}

